fn min(a: &Vec<i32>, n: usize) -> i32 {
    // We assume n > 0 and a.len() >= n
    let mut min_val = a[0];
    for i in 1..n {
        if a[i] < min_val {
            min_val = a[i];
        }
    }
    min_val
}

